mapper.insert:
INSERT INTO rider_stats(
    rider_id, date, orders_count, completed_orders, canceled_orders, 
    total_income, created_at, updated_at
) VALUES (
    #{riderId}, #{date}, #{ordersCount}, #{completedOrders}, #{canceledOrders}, 
    #{totalIncome}, #{createdAt}, #{updatedAt}
) ON DUPLICATE KEY UPDATE 
    orders_count = #{ordersCount}, 
    completed_orders = #{completedOrders}, 
    canceled_orders = #{canceledOrders}, 
    total_income = #{totalIncome}, 
    updated_at = #{updatedAt}

